import {drawPropReference} from './prop-reference-model.js';
export function installPropReference({getProject,library,mutate,redraw}){
 const panel=document.createElement('details');panel.id='sequence-prop-reference';panel.innerHTML='<summary>Show prop · reference layer</summary><p class="hint">Separate artwork for alignment. One prop pixel equals one cat cell. Excluded from cat PNGs, sprite sheets and frame volume; placement is saved with this sequence.</p><label class="field">Prop<select aria-label="Sequence reference prop"></select></label><div class="reference-fields"><label><input data-ref="visible" type="checkbox"> Show prop</label><label>X <input data-ref="x" type="number" min="-96" max="96" step="1" aria-label="Prop reference X"></label><label>Y <input data-ref="y" type="number" min="-96" max="96" step="1" aria-label="Prop reference Y"></label><label><input data-ref="flip" type="checkbox"> Mirror prop</label><label><input data-ref="foreground" type="checkbox"> In front of cat</label><label>Opacity <input data-ref="opacity" type="range" min="0" max="1" step="0.05" aria-label="Prop reference opacity"></label><button type="button">Reload props</button></div><p class="hint" role="status"></p>';
 document.querySelector('.stage').before(panel);
 const select=panel.querySelector('select'),status=panel.querySelector('[role="status"]');let assets=[],loading=false;
 const asset=()=>assets.find(a=>a.id===getProject()?.propReference?.assetId);
 function render(){const ref=getProject()?.propReference,value=ref?.assetId||'';select.replaceChildren(new Option('None',''));for(const a of assets)select.add(new Option(a.name+(a.origin==='ai'&&!/ai draft/i.test(a.name)?' · AI draft':''),a.id));if(value&&!assets.some(a=>a.id===value))select.add(new Option('Unavailable · '+value,value));select.value=value;
  for(const input of panel.querySelectorAll('[data-ref]')){const key=input.dataset.ref;input.disabled=!ref;if(input.type==='checkbox')input.checked=!!ref?.[key];else input.value=ref?.[key]??(key==='opacity'?1:0);}
  status.textContent=value?(asset()?`${asset().width} × ${asset().height} · ${asset().origin} · revision ${asset().revision} · offsets from cat grid top-left`:'This saved asset ID is missing. Reload props or choose another; its placement is retained.'):'Choose a saved prop to preview beside the cat.';
 }
 async function refresh(){if(loading)return;loading=true;try{const response=await fetch('/api/props-workspace');if(response.ok){assets=(await response.json()).workspace.assets;}else if(response.status===404)assets=library()?.savedPropAssets||[];else throw Error('Props unavailable');render();redraw();}catch{status.textContent='Could not reload saved props. Existing reference and sequence retained.';}finally{loading=false;}}
 select.onchange=()=>{const a=assets.find(a=>a.id===select.value);mutate(()=>{if(!a)delete getProject().propReference;else getProject().propReference={assetId:a.id,x:Math.max(-96,24-a.width-1),y:24-a.height,visible:true,flip:false,foreground:false,opacity:1};});};
 for(const input of panel.querySelectorAll('[data-ref]'))input.onchange=()=>{if(!getProject()?.propReference||!input.checkValidity())return;mutate(()=>{getProject().propReference[input.dataset.ref]=input.type==='checkbox'?input.checked:Number(input.value);});};
 panel.querySelector('button').onclick=refresh;panel.addEventListener('toggle',()=>{if(panel.open)refresh();});window.addEventListener('studio-asset-saved',refresh);refresh();
 return {render,draw(ctx,scale,left,top,foreground){const ref=getProject()?.propReference;if(ref&&ref.foreground===foreground)drawPropReference(ctx,asset(),ref,scale,left,top);}};
}
